// IdentityServiceHandler is an implementation of the identity.v1.IdentityService service.
type IdentityServiceHandler interface {
	// Authentication
	BeginOAuthLogin(context.Context, *connect.Request[v1.BeginOAuthLoginRequest]) (*connect.Response[v1.BeginOAuthLoginResponse], error)
	OAuthLogin(context.Context, *connect.Request[v1.OAuthLoginRequest]) (*connect.Response[v1.OAuthLoginResponse], error)
	RedeemOAuthCode(context.Context, *connect.Request[v1.RedeemOAuthCodeRequest]) (*connect.Response[v1.RedeemOAuthCodeResponse], error)
	PasswordSignup(context.Context, *connect.Request[v1.PasswordSignupRequest]) (*connect.Response[v1.PasswordSignupResponse], error)
	PasswordLogin(context.Context, *connect.Request[v1.PasswordLoginRequest]) (*connect.Response[v1.PasswordLoginResponse], error)
	// Passwordless email login (OTP code + magic link)
	RequestEmailLoginCode(context.Context, *connect.Request[v1.RequestEmailLoginCodeRequest]) (*connect.Response[v1.RequestEmailLoginCodeResponse], error)
	VerifyEmailLoginCode(context.Context, *connect.Request[v1.VerifyEmailLoginCodeRequest]) (*connect.Response[v1.VerifyEmailLoginCodeResponse], error)
	RequestMagicLink(context.Context, *connect.Request[v1.RequestMagicLinkRequest]) (*connect.Response[v1.RequestMagicLinkResponse], error)
	RedeemMagicLink(context.Context, *connect.Request[v1.RedeemMagicLinkRequest]) (*connect.Response[v1.RedeemMagicLinkResponse], error)
	// Phone verification (SMS OTP) — proves the authenticated caller owns a phone number
	RequestPhoneVerification(context.Context, *connect.Request[v1.RequestPhoneVerificationRequest]) (*connect.Response[v1.RequestPhoneVerificationResponse], error)
	VerifyPhoneCode(context.Context, *connect.Request[v1.VerifyPhoneCodeRequest]) (*connect.Response[v1.VerifyPhoneCodeResponse], error)
	// Session / Token Auth
	GetCurrentUser(context.Context, *connect.Request[v1.GetCurrentUserRequest]) (*connect.Response[v1.GetCurrentUserResponse], error)
	RefreshToken(context.Context, *connect.Request[v1.RefreshTokenRequest]) (*connect.Response[v1.RefreshTokenResponse], error)
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	// Self-service profile
	UpdateProfile(context.Context, *connect.Request[v1.UpdateProfileRequest]) (*connect.Response[v1.UpdateProfileResponse], error)
	// Password Management
	ChangePassword(context.Context, *connect.Request[v1.ChangePasswordRequest]) (*connect.Response[v1.ChangePasswordResponse], error)
	RequestPasswordReset(context.Context, *connect.Request[v1.RequestPasswordResetRequest]) (*connect.Response[v1.RequestPasswordResetResponse], error)
	ConfirmPasswordReset(context.Context, *connect.Request[v1.ConfirmPasswordResetRequest]) (*connect.Response[v1.ConfirmPasswordResetResponse], error)
	// Email Verification
	SendEmailVerification(context.Context, *connect.Request[v1.SendEmailVerificationRequest]) (*connect.Response[v1.SendEmailVerificationResponse], error)
	VerifyEmail(context.Context, *connect.Request[v1.VerifyEmailRequest]) (*connect.Response[v1.VerifyEmailResponse], error)
	// Email Change (primary-email rotation, double-opt-in)
	RequestEmailChange(context.Context, *connect.Request[v1.RequestEmailChangeRequest]) (*connect.Response[v1.RequestEmailChangeResponse], error)
	ConfirmEmailChange(context.Context, *connect.Request[v1.ConfirmEmailChangeRequest]) (*connect.Response[v1.ConfirmEmailChangeResponse], error)
	// Identity Verification (document + selfie via pluggable provider)
	BeginIdentityVerification(context.Context, *connect.Request[v1.BeginIdentityVerificationRequest]) (*connect.Response[v1.BeginIdentityVerificationResponse], error)
	GetIdentityVerificationStatus(context.Context, *connect.Request[v1.GetIdentityVerificationStatusRequest]) (*connect.Response[v1.GetIdentityVerificationStatusResponse], error)
	// Admin help (replaces self-serve ForgotPassword)
	RequestAdminHelp(context.Context, *connect.Request[v1.RequestAdminHelpRequest]) (*connect.Response[v1.RequestAdminHelpResponse], error)
	ListHelpRequests(context.Context, *connect.Request[v1.ListHelpRequestsRequest]) (*connect.Response[v1.ListHelpRequestsResponse], error)
	ResolveHelpRequest(context.Context, *connect.Request[v1.ResolveHelpRequestRequest]) (*connect.Response[v1.ResolveHelpRequestResponse], error)
	// Passkey / WebAuthn
	BeginPasskeyRegistration(context.Context, *connect.Request[v1.BeginPasskeyRegistrationRequest]) (*connect.Response[v1.BeginPasskeyRegistrationResponse], error)
	CompletePasskeyRegistration(context.Context, *connect.Request[v1.CompletePasskeyRegistrationRequest]) (*connect.Response[v1.CompletePasskeyRegistrationResponse], error)
	BeginPasskeyLogin(context.Context, *connect.Request[v1.BeginPasskeyLoginRequest]) (*connect.Response[v1.BeginPasskeyLoginResponse], error)
	CompletePasskeyLogin(context.Context, *connect.Request[v1.CompletePasskeyLoginRequest]) (*connect.Response[v1.CompletePasskeyLoginResponse], error)
	ListPasskeys(context.Context, *connect.Request[v1.ListPasskeysRequest]) (*connect.Response[v1.ListPasskeysResponse], error)
	DeletePasskey(context.Context, *connect.Request[v1.DeletePasskeyRequest]) (*connect.Response[v1.DeletePasskeyResponse], error)
	// QR Login (cross-device authorization)
	InitiateQrLogin(context.Context, *connect.Request[v1.InitiateQrLoginRequest]) (*connect.Response[v1.InitiateQrLoginResponse], error)
	GetQrLoginSession(context.Context, *connect.Request[v1.GetQrLoginSessionRequest]) (*connect.Response[v1.GetQrLoginSessionResponse], error)
	ApproveQrLogin(context.Context, *connect.Request[v1.ApproveQrLoginRequest]) (*connect.Response[v1.ApproveQrLoginResponse], error)
	PollQrLogin(context.Context, *connect.Request[v1.PollQrLoginRequest]) (*connect.Response[v1.PollQrLoginResponse], error)
	// 2FA TOTP
	BeginTotpSetup(context.Context, *connect.Request[v1.BeginTotpSetupRequest]) (*connect.Response[v1.BeginTotpSetupResponse], error)
	VerifyTotpSetup(context.Context, *connect.Request[v1.VerifyTotpSetupRequest]) (*connect.Response[v1.VerifyTotpSetupResponse], error)
	DisableTotp(context.Context, *connect.Request[v1.DisableTotpRequest]) (*connect.Response[v1.DisableTotpResponse], error)
	VerifyTotp(context.Context, *connect.Request[v1.VerifyTotpRequest]) (*connect.Response[v1.VerifyTotpResponse], error)
	RegenerateRecoveryCodes(context.Context, *connect.Request[v1.RegenerateRecoveryCodesRequest]) (*connect.Response[v1.RegenerateRecoveryCodesResponse], error)
	// Session management
	ListMySessions(context.Context, *connect.Request[v1.ListMySessionsRequest]) (*connect.Response[v1.ListMySessionsResponse], error)
	RevokeSession(context.Context, *connect.Request[v1.RevokeSessionRequest]) (*connect.Response[v1.RevokeSessionResponse], error)
	RevokeAllSessions(context.Context, *connect.Request[v1.RevokeAllSessionsRequest]) (*connect.Response[v1.RevokeAllSessionsResponse], error)
	SignOutEverywhere(context.Context, *connect.Request[v1.SignOutEverywhereRequest]) (*connect.Response[v1.SignOutEverywhereResponse], error)
	// Audit log
	ListAuditEvents(context.Context, *connect.Request[v1.ListAuditEventsRequest]) (*connect.Response[v1.ListAuditEventsResponse], error)
	// Users
	CreateUser(context.Context, *connect.Request[v1.CreateUserRequest]) (*connect.Response[v1.CreateUserResponse], error)
	GetUser(context.Context, *connect.Request[v1.GetUserRequest]) (*connect.Response[v1.GetUserResponse], error)
	UpdateUser(context.Context, *connect.Request[v1.UpdateUserRequest]) (*connect.Response[v1.UpdateUserResponse], error)
	DeleteUser(context.Context, *connect.Request[v1.DeleteUserRequest]) (*connect.Response[v1.DeleteUserResponse], error)
	// Admin-only paginated user listing — supports filters and search.
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	// Groups (formerly WorkingGroup — graph DB type still WorkingGroup)
	CreateGroup(context.Context, *connect.Request[v1.CreateGroupRequest]) (*connect.Response[v1.CreateGroupResponse], error)
	UpdateGroup(context.Context, *connect.Request[v1.UpdateGroupRequest]) (*connect.Response[v1.UpdateGroupResponse], error)
	DeleteGroup(context.Context, *connect.Request[v1.DeleteGroupRequest]) (*connect.Response[v1.DeleteGroupResponse], error)
	ListGroups(context.Context, *connect.Request[v1.ListGroupsRequest]) (*connect.Response[v1.ListGroupsResponse], error)
	// Membership (graph edges)
	AddGroupMember(context.Context, *connect.Request[v1.AddGroupMemberRequest]) (*connect.Response[v1.AddGroupMemberResponse], error)
	RemoveGroupMember(context.Context, *connect.Request[v1.RemoveGroupMemberRequest]) (*connect.Response[v1.RemoveGroupMemberResponse], error)
	ListGroupMembers(context.Context, *connect.Request[v1.ListGroupMembersRequest]) (*connect.Response[v1.ListGroupMembersResponse], error)
	// Tenant domains (redesign). Authenticated, project-scoped, and gated
	// on the caller being an owner/admin member of the target tenant — with
	// one exception: VerifyDomain on a still-latent tenant that has no
	// members yet is open, so the first verifier becomes its owner.
	// Available only on the postgres control-plane driver; the memory driver
	// deployments return Unimplemented.
	CreateDomain(context.Context, *connect.Request[v1.CreateDomainRequest]) (*connect.Response[v1.CreateDomainResponse], error)
	VerifyDomain(context.Context, *connect.Request[v1.VerifyDomainRequest]) (*connect.Response[v1.VerifyDomainResponse], error)
	ListTenantDomains(context.Context, *connect.Request[v1.ListTenantDomainsRequest]) (*connect.Response[v1.ListTenantDomainsResponse], error)
	// Tenant membership (redesign). Authenticated, project-scoped, and —
	// except for AcceptTenantInvitation — gated on the caller being an
	// owner/admin member of the target tenant. AcceptTenantInvitation is the
	// redeemer's own action: any authenticated caller may redeem a token, but
	// only for an invitation addressed to their own account email. Available
	// only on the postgres control-plane driver; memory deployments
	// return Unimplemented.
	CreateTenantInvitation(context.Context, *connect.Request[v1.CreateTenantInvitationRequest]) (*connect.Response[v1.CreateTenantInvitationResponse], error)
	AcceptTenantInvitation(context.Context, *connect.Request[v1.AcceptTenantInvitationRequest]) (*connect.Response[v1.AcceptTenantInvitationResponse], error)
	ListTenantInvitations(context.Context, *connect.Request[v1.ListTenantInvitationsRequest]) (*connect.Response[v1.ListTenantInvitationsResponse], error)
	ListTenantMembers(context.Context, *connect.Request[v1.ListTenantMembersRequest]) (*connect.Response[v1.ListTenantMembersResponse], error)
	RemoveTenantMember(context.Context, *connect.Request[v1.RemoveTenantMemberRequest]) (*connect.Response[v1.RemoveTenantMemberResponse], error)
	// Admin user management (caller must have role=admin). Enforced in the
	// servicer via _require_admin(ctx); all admin RPCs audit-log their actions.
	InviteUser(context.Context, *connect.Request[v1.InviteUserRequest]) (*connect.Response[v1.InviteUserResponse], error)
	AcceptInvitation(context.Context, *connect.Request[v1.AcceptInvitationRequest]) (*connect.Response[v1.AcceptInvitationResponse], error)
	DeactivateUser(context.Context, *connect.Request[v1.DeactivateUserRequest]) (*connect.Response[v1.DeactivateUserResponse], error)
	ReactivateUser(context.Context, *connect.Request[v1.ReactivateUserRequest]) (*connect.Response[v1.ReactivateUserResponse], error)
	ResetUserPassword(context.Context, *connect.Request[v1.ResetUserPasswordRequest]) (*connect.Response[v1.ResetUserPasswordResponse], error)
	SetUserQuota(context.Context, *connect.Request[v1.SetUserQuotaRequest]) (*connect.Response[v1.SetUserQuotaResponse], error)
	// Control-plane admin (redesign). PLATFORM-operator RPCs that provision
	// projects/tenants/credentials out-of-band. Authenticated by the shared
	// admin secret in the "X-Admin-Secret" header (NOT a user JWT); disabled
	// (UNIMPLEMENTED) unless GATEWAY_ADMIN_API_SECRET is set.
	AdminCreateProject(context.Context, *connect.Request[v1.AdminCreateProjectRequest]) (*connect.Response[v1.AdminCreateProjectResponse], error)
	AdminCreateProjectCredential(context.Context, *connect.Request[v1.AdminCreateProjectCredentialRequest]) (*connect.Response[v1.AdminCreateProjectCredentialResponse], error)
	AdminAddProjectAuthDomain(context.Context, *connect.Request[v1.AdminAddProjectAuthDomainRequest]) (*connect.Response[v1.AdminAddProjectAuthDomainResponse], error)
	// Customer-owned custom auth-domains: a project registers a serving
	// hostname, proves ownership via a DNS TXT challenge, then it resolves.
	// An unverified custom domain does NOT resolve requests.
	AddProjectAuthDomain(context.Context, *connect.Request[v1.AddProjectAuthDomainRequest]) (*connect.Response[v1.AddProjectAuthDomainResponse], error)
	VerifyProjectAuthDomain(context.Context, *connect.Request[v1.VerifyProjectAuthDomainRequest]) (*connect.Response[v1.VerifyProjectAuthDomainResponse], error)
	ListProjectAuthDomains(context.Context, *connect.Request[v1.ListProjectAuthDomainsRequest]) (*connect.Response[v1.ListProjectAuthDomainsResponse], error)
	// SetPrimaryAuthDomain promotes a VERIFIED custom auth-domain to the
	// project's primary serving host, atomically demoting the current primary in
	// the same transaction. Only a verified domain may be promoted.
	SetPrimaryAuthDomain(context.Context, *connect.Request[v1.SetPrimaryAuthDomainRequest]) (*connect.Response[v1.SetPrimaryAuthDomainResponse], error)
	AdminCreateTenant(context.Context, *connect.Request[v1.AdminCreateTenantRequest]) (*connect.Response[v1.AdminCreateTenantResponse], error)
	AdminAddTenantAdmin(context.Context, *connect.Request[v1.AdminAddTenantAdminRequest]) (*connect.Response[v1.AdminAddTenantAdminResponse], error)
	// Zero-config bootstrap of the FIRST platform admin. NOT secret-gated:
	// succeeds only while platform_admins is empty, then permanently closes
	// (FAILED_PRECONDITION). Postgres-only; the memory driver returns UNIMPLEMENTED.
	CreateFirstPlatformAdmin(context.Context, *connect.Request[v1.CreateFirstPlatformAdminRequest]) (*connect.Response[v1.CreateFirstPlatformAdminResponse], error)
	// RBAC: custom scoped roles + assignments. ADDITIVE least-privilege layer
	// on top of the legacy free-text user.role field. An admin defines a role
	// naming an explicit permission subset, assigns it to a user, and the
	// permission-check helper enforces it ALONGSIDE the existing role==admin
	// checks (admin/owner remain a full-access superset). Admin-only; the JWT
	// must carry role=admin.
	CreateRole(context.Context, *connect.Request[v1.CreateRoleRequest]) (*connect.Response[v1.CreateRoleResponse], error)
	ListRoles(context.Context, *connect.Request[v1.ListRolesRequest]) (*connect.Response[v1.ListRolesResponse], error)
	DeleteRole(context.Context, *connect.Request[v1.DeleteRoleRequest]) (*connect.Response[v1.DeleteRoleResponse], error)
	AssignRole(context.Context, *connect.Request[v1.AssignRoleRequest]) (*connect.Response[v1.AssignRoleResponse], error)
	GetUserPermissions(context.Context, *connect.Request[v1.GetUserPermissionsRequest]) (*connect.Response[v1.GetUserPermissionsResponse], error)
}

